create table public.business_recruitment_requisitions(
 id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.business_tenants(id),code text not null check(char_length(code) between 1 and 50),name text not null check(char_length(name) between 2 and 180),notes text not null default '' check(char_length(notes)<=2000),status text not null default 'draft' check(status in ('draft','posted','cancelled')),row_version integer not null default 1 check(row_version>0),created_by uuid not null,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),reviewed_by uuid,calculation_snapshot jsonb,posted_journal_id uuid,reversed_journal_id uuid,
 department text not null,position text not null,headcount integer not null check(headcount between 1 and 10000),employment_type text not null check(employment_type in ('full_time','part_time','seasonal','contract')),opened_on date not null,target_on date not null,salary_min numeric(24,4),salary_max numeric(24,4),hiring_manager_id uuid not null,project_id uuid,document_date date not null,
 unique(tenant_id,id),unique(tenant_id,code),foreign key(tenant_id,created_by) references public.business_accounts(tenant_id,id),foreign key(tenant_id,reviewed_by) references public.business_accounts(tenant_id,id),foreign key(tenant_id,hiring_manager_id) references public.business_staff(tenant_id,id),foreign key(tenant_id,project_id) references public.business_projects(tenant_id,id),check(target_on>=opened_on),check(salary_min is null or salary_max is null or salary_max>=salary_min)
);
create index business_recruitment_requisitions_open_idx on public.business_recruitment_requisitions(tenant_id,target_on,department) where status='posted';
alter table public.business_recruitment_requisitions enable row level security;
revoke all on public.business_recruitment_requisitions from public,anon,authenticated,service_role;

create table public.business_recruitment_job_posts(
 id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.business_tenants(id),code text not null check(char_length(code) between 1 and 50),name text not null check(char_length(name) between 2 and 180),notes text not null default '' check(char_length(notes)<=2000),status text not null default 'draft' check(status in ('draft','posted','cancelled')),row_version integer not null default 1 check(row_version>0),created_by uuid not null,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),reviewed_by uuid,calculation_snapshot jsonb,posted_journal_id uuid,reversed_journal_id uuid,
 requisition_id uuid not null,channel text not null check(channel in ('company_site','job_board','agency','social','other')),published_on date not null,closes_on date not null,headline text not null check(char_length(btrim(headline)) between 3 and 180),content text not null check(char_length(btrim(content)) between 10 and 4000),document_date date not null,
 unique(tenant_id,id),unique(tenant_id,code),foreign key(tenant_id,created_by) references public.business_accounts(tenant_id,id),foreign key(tenant_id,reviewed_by) references public.business_accounts(tenant_id,id),foreign key(tenant_id,requisition_id) references public.business_recruitment_requisitions(tenant_id,id),check(closes_on>=published_on)
);
create index business_recruitment_job_posts_live_idx on public.business_recruitment_job_posts(tenant_id,requisition_id,closes_on) where status='posted';
alter table public.business_recruitment_job_posts enable row level security;
revoke all on public.business_recruitment_job_posts from public,anon,authenticated,service_role;
create function public.business_recruitment_job_post_guard() returns trigger language plpgsql security definer set search_path='' as $$
begin
 if tg_op='UPDATE' and old.status='posted' and (new.requisition_id,new.channel,new.published_on,new.closes_on,new.headline,new.content,new.document_date,new.name,new.notes) is distinct from (old.requisition_id,old.channel,old.published_on,old.closes_on,old.headline,old.content,old.document_date,old.name,old.notes) then raise exception 'BUSINESS_RECORD_LOCKED';end if;
 if new.status='posted' and not exists(select 1 from public.business_recruitment_requisitions r where r.tenant_id=new.tenant_id and r.id=new.requisition_id and r.status='posted' and r.target_on>=new.closes_on) then raise exception 'BUSINESS_INVALID_REQUISITION';end if;return new;
end $$;
revoke all on function public.business_recruitment_job_post_guard() from public,anon,authenticated,service_role;
create trigger business_recruitment_job_post_guard before insert or update on public.business_recruitment_job_posts for each row execute function public.business_recruitment_job_post_guard();

