 requisition_id uuid not null,job_post_id uuid,email text not null check(char_length(email) between 3 and 254),phone text,source text not null check(source in ('referral','job_board','agency','direct','other')),applied_on date not null,years_experience numeric(8,2) check(years_experience is null or years_experience>=0),candidate_status text not null default 'applied' check(candidate_status in ('applied','screening','interview','rejected','offer','hired')),consent_granted boolean not null,consented_on date not null,consent_expires_on date not null,staff_id uuid,document_date date not null,
 unique(tenant_id,id),unique(tenant_id,code),foreign key(tenant_id,created_by) references public.business_accounts(tenant_id,id),foreign key(tenant_id,reviewed_by) references public.business_accounts(tenant_id,id),foreign key(tenant_id,requisition_id) references public.business_recruitment_requisitions(tenant_id,id),foreign key(tenant_id,job_post_id) references public.business_recruitment_job_posts(tenant_id,id),foreign key(tenant_id,staff_id) references public.business_staff(tenant_id,id),check(consent_expires_on>=consented_on)
);
create unique index business_recruitment_candidate_email_idx on public.business_recruitment_candidates(tenant_id,requisition_id,lower(email));
