create function public.business_recruitment_requisition_guard() returns trigger language plpgsql security definer set search_path='' as $$
begin
 if tg_op='UPDATE' and old.status='posted' and (new.department,new.position,new.headcount,new.employment_type,new.opened_on,new.target_on,new.salary_min,new.salary_max,new.hiring_manager_id,new.project_id,new.document_date,new.name,new.notes) is distinct from (old.department,old.position,old.headcount,old.employment_type,old.opened_on,old.target_on,old.salary_min,old.salary_max,old.hiring_manager_id,old.project_id,old.document_date,old.name,old.notes) then raise exception 'BUSINESS_RECORD_LOCKED';end if;
 if new.status='posted' and not exists(select 1 from public.business_staff s where s.tenant_id=new.tenant_id and s.id=new.hiring_manager_id and s.status='active') then raise exception 'BUSINESS_INVALID_REFERENCE';end if;return new;
end $$;
revoke all on function public.business_recruitment_requisition_guard() from public,anon,authenticated,service_role;
create trigger business_recruitment_requisition_guard before insert or update on public.business_recruitment_requisitions for each row execute function public.business_recruitment_requisition_guard();

create function public.business_recruitment_candidate_guard() returns trigger language plpgsql security definer set search_path='' as $$
declare next_stage_valid boolean:=false;
begin
 if tg_op='UPDATE' and old.status='posted' and (new.requisition_id,new.job_post_id,new.email,new.phone,new.source,new.applied_on,new.years_experience,new.consent_granted,new.consented_on,new.consent_expires_on,new.document_date,new.name,new.notes) is distinct from (old.requisition_id,old.job_post_id,old.email,old.phone,old.source,old.applied_on,old.years_experience,old.consent_granted,old.consented_on,old.consent_expires_on,old.document_date,old.name,old.notes) then raise exception 'BUSINESS_RECORD_LOCKED';end if;
 if tg_op='UPDATE' and old.status='posted' and new.staff_id is distinct from old.staff_id and not exists(select 1 from public.business_recruitment_hires h where h.tenant_id=new.tenant_id and h.candidate_id=new.id and h.staff_id=new.staff_id and h.status='posted') then raise exception 'BUSINESS_RECORD_LOCKED';end if;
 if new.status='posted' then
  if not new.consent_granted or new.consented_on>current_date or new.consent_expires_on<current_date then raise exception 'BUSINESS_CANDIDATE_CONSENT_REQUIRED';end if;
  if not exists(select 1 from public.business_recruitment_requisitions r where r.tenant_id=new.tenant_id and r.id=new.requisition_id and r.status='posted' and r.target_on>=new.applied_on) then raise exception 'BUSINESS_INVALID_REFERENCE';end if;
  if new.job_post_id is not null and (new.source<>'job_board' or not exists(select 1 from public.business_recruitment_job_posts p where p.tenant_id=new.tenant_id and p.id=new.job_post_id and p.requisition_id=new.requisition_id and p.status='posted' and p.channel='job_board' and p.published_on<=new.applied_on and p.closes_on>=new.applied_on)) then raise exception 'BUSINESS_INVALID_JOB_POST';end if;
  if tg_op='UPDATE' and old.candidate_status is distinct from new.candidate_status then
   if new.candidate_status='screening' then select exists(select 1 from public.business_recruitment_interviews i where i.tenant_id=new.tenant_id and i.candidate_id=new.id and i.status='posted' and i.stage='screening' and i.decision='advance') into next_stage_valid;
   elsif new.candidate_status='interview' then select exists(select 1 from public.business_recruitment_interviews i where i.tenant_id=new.tenant_id and i.candidate_id=new.id and i.status='posted' and i.stage<>'screening' and i.decision='advance') into next_stage_valid;
   elsif new.candidate_status='rejected' then select exists(select 1 from public.business_recruitment_interviews i where i.tenant_id=new.tenant_id and i.candidate_id=new.id and i.status='posted' and i.decision='reject') into next_stage_valid;
   elsif new.candidate_status='offer' then select exists(select 1 from public.business_recruitment_offers o where o.tenant_id=new.tenant_id and o.candidate_id=new.id and o.status='posted') into next_stage_valid;
   elsif new.candidate_status='hired' then select exists(select 1 from public.business_recruitment_hires h join public.business_staff s on s.tenant_id=h.tenant_id and s.id=h.staff_id where h.tenant_id=new.tenant_id and h.candidate_id=new.id and h.status='posted' and h.staff_id=new.staff_id and s.status='active') into next_stage_valid;end if;
   if not next_stage_valid then raise exception 'BUSINESS_INVALID_CANDIDATE_TRANSITION';end if;
  end if;
 end if;return new;
end $$;
revoke all on function public.business_recruitment_candidate_guard() from public,anon,authenticated,service_role;
create trigger business_recruitment_candidate_guard before insert or update on public.business_recruitment_candidates for each row execute function public.business_recruitment_candidate_guard();

create function public.business_recruitment_interview_guard() returns trigger language plpgsql security definer set search_path='' as $$
declare c public.business_recruitment_candidates%rowtype;
begin
 if tg_op='UPDATE' and old.status='posted' and (new.candidate_id,new.interview_on,new.stage,new.interviewer_id,new.score,new.decision,new.feedback,new.document_date,new.name,new.notes) is distinct from (old.candidate_id,old.interview_on,old.stage,old.interviewer_id,old.score,old.decision,old.feedback,old.document_date,old.name,old.notes) then raise exception 'BUSINESS_RECORD_LOCKED';end if;
 if new.status='posted' and (tg_op='INSERT' or old.status<>'posted') then select * into c from public.business_recruitment_candidates where tenant_id=new.tenant_id and id=new.candidate_id for key share;if not found or c.status<>'posted' or c.candidate_status not in ('applied','screening','interview') then raise exception 'BUSINESS_INVALID_CANDIDATE_STAGE';end if;if not exists(select 1 from public.business_staff where tenant_id=new.tenant_id and id=new.interviewer_id and status='active') then raise exception 'BUSINESS_INVALID_REFERENCE';end if;end if;return new;
end $$;
revoke all on function public.business_recruitment_interview_guard() from public,anon,authenticated,service_role;
create trigger business_recruitment_interview_guard before insert or update on public.business_recruitment_interviews for each row execute function public.business_recruitment_interview_guard();
create function public.business_recruitment_interview_advance() returns trigger language plpgsql security definer set search_path='' as $$
begin if new.status='posted' and old.status<>'posted' then if new.decision='advance' then update public.business_recruitment_candidates set candidate_status=case when new.stage='screening' then 'screening' else 'interview' end,row_version=row_version+1,updated_at=now() where tenant_id=new.tenant_id and id=new.candidate_id and candidate_status in ('applied','screening','interview');elsif new.decision='reject' then update public.business_recruitment_candidates set candidate_status='rejected',row_version=row_version+1,updated_at=now() where tenant_id=new.tenant_id and id=new.candidate_id and candidate_status in ('applied','screening','interview');end if;end if;return new;end $$;
revoke all on function public.business_recruitment_interview_advance() from public,anon,authenticated,service_role;
create trigger business_recruitment_interview_advance after update on public.business_recruitment_interviews for each row execute function public.business_recruitment_interview_advance();

create function public.business_recruitment_offer_guard() returns trigger language plpgsql security definer set search_path='' as $$
declare c public.business_recruitment_candidates%rowtype;r public.business_recruitment_requisitions%rowtype;
begin
 if tg_op='UPDATE' and old.status='posted' and (new.candidate_id,new.offered_on,new.expires_on,new.proposed_start_on,new.monthly_salary,new.benefits,new.document_date,new.name,new.notes) is distinct from (old.candidate_id,old.offered_on,old.expires_on,old.proposed_start_on,old.monthly_salary,old.benefits,old.document_date,old.name,old.notes) then raise exception 'BUSINESS_RECORD_LOCKED';end if;
 if new.status='posted' and (tg_op='INSERT' or old.status<>'posted') then select * into c from public.business_recruitment_candidates where tenant_id=new.tenant_id and id=new.candidate_id for key share;if not found or c.status<>'posted' or c.candidate_status<>'interview' then raise exception 'BUSINESS_INVALID_CANDIDATE_STAGE';end if;select * into r from public.business_recruitment_requisitions where tenant_id=c.tenant_id and id=c.requisition_id;if r.salary_min is not null and new.monthly_salary<r.salary_min or r.salary_max is not null and new.monthly_salary>r.salary_max then raise exception 'BUSINESS_OFFER_OUTSIDE_APPROVED_RANGE';end if;end if;return new;
end $$;
revoke all on function public.business_recruitment_offer_guard() from public,anon,authenticated,service_role;
create trigger business_recruitment_offer_guard before insert or update on public.business_recruitment_offers for each row execute function public.business_recruitment_offer_guard();
create function public.business_recruitment_offer_advance() returns trigger language plpgsql security definer set search_path='' as $$
begin if new.status='posted' and old.status<>'posted' then update public.business_recruitment_candidates set candidate_status='offer',row_version=row_version+1,updated_at=now() where tenant_id=new.tenant_id and id=new.candidate_id and candidate_status='interview';end if;return new;end $$;
revoke all on function public.business_recruitment_offer_advance() from public,anon,authenticated,service_role;
create trigger business_recruitment_offer_advance after update on public.business_recruitment_offers for each row execute function public.business_recruitment_offer_advance();

create function public.business_recruitment_hire_guard() returns trigger language plpgsql security definer set search_path='' as $$
declare c public.business_recruitment_candidates%rowtype;o public.business_recruitment_offers%rowtype;
begin
 if tg_op='UPDATE' and old.status='posted' and (new.candidate_id,new.offer_id,new.staff_id,new.accepted_on,new.start_on,new.employment_contract_id,new.document_date,new.name,new.notes) is distinct from (old.candidate_id,old.offer_id,old.staff_id,old.accepted_on,old.start_on,old.employment_contract_id,old.document_date,old.name,old.notes) then raise exception 'BUSINESS_RECORD_LOCKED';end if;
 if new.status='posted' and (tg_op='INSERT' or old.status<>'posted') then select * into c from public.business_recruitment_candidates where tenant_id=new.tenant_id and id=new.candidate_id for key share;if not found or c.status<>'posted' or c.candidate_status<>'offer' then raise exception 'BUSINESS_INVALID_CANDIDATE_STAGE';end if;select * into o from public.business_recruitment_offers where tenant_id=new.tenant_id and id=new.offer_id and candidate_id=new.candidate_id for key share;if not found or o.status<>'posted' or new.accepted_on>o.expires_on then raise exception 'BUSINESS_INVALID_OFFER';end if;if not exists(select 1 from public.business_staff where tenant_id=new.tenant_id and id=new.staff_id and status='active') then raise exception 'BUSINESS_INVALID_REFERENCE';end if;if new.employment_contract_id is not null and not exists(select 1 from public.business_employment_contracts where tenant_id=new.tenant_id and id=new.employment_contract_id and staff_id=new.staff_id and starts_on=new.start_on and status='posted') then raise exception 'BUSINESS_INVALID_EMPLOYMENT_CONTRACT';end if;end if;return new;
end $$;
revoke all on function public.business_recruitment_hire_guard() from public,anon,authenticated,service_role;
create trigger business_recruitment_hire_guard before insert or update on public.business_recruitment_hires for each row execute function public.business_recruitment_hire_guard();
create function public.business_recruitment_hire_complete() returns trigger language plpgsql security definer set search_path='' as $$
begin if new.status='posted' and old.status<>'posted' then update public.business_recruitment_candidates set candidate_status='hired',staff_id=new.staff_id,row_version=row_version+1,updated_at=now() where tenant_id=new.tenant_id and id=new.candidate_id and candidate_status='offer';end if;return new;end $$;
revoke all on function public.business_recruitment_hire_complete() from public,anon,authenticated,service_role;
create trigger business_recruitment_hire_complete after update on public.business_recruitment_hires for each row execute function public.business_recruitment_hire_complete();

do $$
declare body text;anchor text;replacement text;
begin select pg_get_functiondef('public.business_misa_effect(uuid,uuid,text,jsonb,text,text)'::regprocedure) into body;anchor:='elsif p_kind in (''safety_incidents'',''quality_nonconformances'',''corrective_actions'') then return jsonb_build_object(''lines'',''[]''::jsonb);';replacement:=anchor||E'\n'||' elsif p_kind in (''recruitment_requisitions'',''recruitment_job_posts'',''recruitment_candidates'',''recruitment_interviews'',''recruitment_offers'',''recruitment_hires'') then return jsonb_build_object(''lines'',''[]''::jsonb);';if strpos(body,anchor)=0 then raise exception 'Review MISA dispatch before adding recruiting workflows';end if;execute replace(body,anchor,replacement);end $$;
